protocol Feed {
    associatedtype Item
    func first() -> Item?
}
struct IDFeed: Feed {
    typealias Item = Int
    let ids: [Int]
    func first() -> Int? { ids.first }
}
struct NameFeed: Feed {
    let names: [String]
    func first() -> String? { names.first }
}
func sameFirst<A: Feed, B: Feed>(_ a: A, _ b: B) -> Bool
where A.Item == B.Item, A.Item: Equatable {
    a.first() == b.first()
}
struct SavedIDs: Feed {
    let ids: [Int]
    func first() -> Int? { ids.first }
}
print(sameFirst(IDFeed(ids: [71]), SavedIDs(ids: [71])))

Пример печатает true; два пустых источника также дают true по сравнению Optional.

